import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s\'"<>]+'
    urls = re.findall(url_pattern, myString)
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc.split('@')[-1].split(':')[0]
        if domain:
            domains.add(domain)
    result = {}
    for domain in domains:
        try:
            api_url = f"http://ip-api.com/json/{domain}"
            if API_KEY:
                api_url += f"?key={urllib.parse.quote(API_KEY)}"
            response = requests.get(api_url, timeout=10)
            if response.status_code == 200:
                try:
                    data = json.loads(response.text)
                except json.JSONDecodeError:
                    data = None
            else:
                data = None
        except requests.RequestException:
            data = None
        result[domain] = data
    return result

