import collections
import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    url = API_URL.rstrip('/') + '/' + user + '/repos'
    response = requests.get(url)
    try:
        data = json.loads(response.text)
    except Exception:
        return []
    Repo = collections.namedtuple('Repo', ['name', 'created_at'])
    repos = []
    if isinstance(data, list):
        for item in data:
            name = item.get('name')
            created_at = item.get('created_at')
            if name is not None and created_at is not None:
                repos.append(Repo(name=name, created_at=created_at))
    repos_sorted = sorted(repos, key=lambda r: r.created_at)
    return [r.name for r in repos_sorted]

import collections
import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    url = f"{API_URL}{user}/repos"
    response = requests.get(url)
    try:
        data = json.loads(response.text)
    except json.JSONDecodeError:
        return []
    if not isinstance(data, list):
        return []
    repos = []
    for repo in data:
        name = repo.get("name")
        created_at = repo.get("created_at")
        if name is not None and created_at is not None:
            repos.append((created_at, name))
    repos.sort(key=lambda x: x[0])
    return [name for _, name in repos]

import json
from datetime import datetime
def task_func(json_data):
