import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {}
    text = json.dumps(data, ensure_ascii=False)
    pattern = r'https?://[^\s"\'<>]+'
    urls = re.findall(pattern, text)
    counts = Counter(urls)
    if top_n is not None:
        counts = Counter(dict(counts.most_common(top_n)))
    return dict(counts)

import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    try:
        data = json.loads(ip_address)
    except json.JSONDecodeError:
        return 'Invalid IP address received'
    ip = None
    if isinstance(data, dict):
        for value in data.values():
            if isinstance(value, str) and re.fullmatch(IP_REGEX, value):
                ip = value
                break
    if ip is None or not re.fullmatch(IP_REGEX, ip):
        return 'Invalid IP address received'
    return ip

