            for v in obj.values():
                yield from extract_strings(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from extract_strings(item)
        elif isinstance(obj, str):
            yield obj
    urls = []
    for s in extract_strings(data):
        urls.extend(url_pattern.findall(s))
    counts = Counter(urls)
    if top_n is not None:
        most_common = counts.most_common(top_n)
        return {k: v for k, v in most_common}
    return dict(counts)

