            for item in data:
                candidate = str(item)
                match = re.search(IP_REGEX, candidate)
                if match:
                    ip = match.group(0)
                    break
    except Exception:
        pass
    if not ip:
        match = re.search(IP_REGEX, content)
        if match:
            ip = match.group(0)
    if not ip:
        raise Exception('Unable to determine public IP address from response')
    return ip

