import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}

    email_pattern = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')

    def process(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                processed_value = process(v)
                if processed_value is not None or not isinstance(v, type(None)):
                    new_dict[k] = processed_value
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                processed_item = process(item)
                if processed_item is not None or not isinstance(item, type(None)):
                    new_list.append(processed_item)
            return new_list
        elif isinstance(obj, str):
            if email_pattern.search(obj):
                return REPLACE_NONE
            return obj
        else:
            return obj

    processed_data = process(data)

    def collect_values(obj, collected):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, collected)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item, collected)
        else:
            collected.append(obj)

    values = []
    collect_values(processed_data, values)
    value_counts = Counter(values)

    return {"data": processed_data, "value_counts": value_counts}

