import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except Exception:
        raise ValueError("Malformed JSON data")

    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data must be a non-empty list")

    records = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item must be a dictionary")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Missing Country or Population field")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population_int = int(math.floor(population))
        records.append({"Country": country, "Population": population_int})

    df = pd.DataFrame(records, columns=["Country", "Population"])

    if not os.path.isdir(output_dir):
        try:
            os.makedirs(output_dir, exist_ok=True)
        except Exception as e:
            raise IOError(f"Cannot create directory: {e}")

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Failed to write CSV file: {e}")

    return file_path, df

