import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if json_data is None:
        raise ValueError("JSON data is None")
    if isinstance(json_data, str):
        json_str = json_data.strip()
        if not json_str:
            raise ValueError("Empty JSON data")
        try:
            data = json.loads(json_str)
        except Exception as e:
            raise ValueError("Malformed JSON data") from e
    else:
        data = json_data
    if isinstance(data, dict):
        records = [data]
    elif isinstance(data, list):
        records = data
    else:
        raise ValueError("JSON data must be an object or array of objects")
    rows = []
    for item in records:
        if not isinstance(item, dict):
            raise ValueError("Each record must be a JSON object")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Missing Country or Population field")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        country = country.strip()
        if not country:
            raise ValueError("Country name cannot be empty")
        if isinstance(population, bool):
            raise ValueError("Population must be numeric")
        try:
            population_num = float(population)
        except Exception:
            raise ValueError("Population must be numeric")
        if math.isnan(population_num) or math.isinf(population_num):
            raise ValueError("Population must be a finite number")
        if population_num < 0:
            raise ValueError("Population cannot be negative")
